-- generated by scripts/build_narrator_groups.py: printed narrator spellings grouped into people
create table if not exists narrator_groups (spelling text primary key, gkey text not null, label text not null);
create index if not exists narrator_groups_gkey on narrator_groups (gkey);
alter table narrator_groups enable row level security;
drop policy if exists narrator_groups_read on narrator_groups;
create policy narrator_groups_read on narrator_groups for select using (true);
grant select on narrator_groups to anon, authenticated;
truncate narrator_groups;
select g2.spelling, s.narrator_id
from narrator_spellings s
join narrator_groups g1 on g1.spelling = s.spelling
join narrator_groups g2 on g2.gkey = g1.gkey
where not exists (select 1 from narrator_spellings x where x.spelling = g2.spelling)
group by g2.spelling, s.narrator_id;
